const body = $json.body || $json || {};
const payload = body.data || body;
const text = (payload.text || payload.message || payload.msg || '').toString().trim();
const phone = (payload.from || payload.sender || payload.number || '').toString().trim();
const instance = (payload.instanceName || payload.instance || 'default').toString();
const type = (payload.type || 'text').toString();

const cleanText = text.toLowerCase();

return {
  phone,
  text,
  cleanText,
  instance,
  type,
  receivedAt: new Date().toISOString(),
  raw: body
};

const phone = $json.phone || '';
const text = ($json.text || '').trim();
const normalized = text.toLowerCase();
const session = ($json.rows && $json.rows[0]) || null;
const etapa = session && session.etapa ? session.etapa : 'INICIO';
const dados = session && session.dados_temporarios ? session.dados_temporarios : {};

let responseType = 'MENU';
let nextStage = etapa;
let payload = { phone, text, etapa, dados, instance: $json.instance || 'default' };

if (['oi','olá','hello','hi','menu','inicio','iniciar'].includes(normalized)) {
  responseType = 'MENU';
  nextStage = 'INICIO';
} else if (['1','catalogo','catálogo','produtos','ver produtos'].includes(normalized)) {
  responseType = 'CATALOGO';
  nextStage = 'CATALOGO';
} else if (['2','carrinho','ver carrinho','checkout'].includes(normalized)) {
  responseType = 'CARRINHO';
  nextStage = 'CARRINHO';
} else if (['3','finalizar','fechar pedido','confirmar'].includes(normalized)) {
  responseType = 'CONFIRMAR';
  nextStage = 'CONFIRMAR';
} else if (['4','pix','pagar','pagamento'].includes(normalized)) {
  responseType = 'PAGAMENTO';
  nextStage = 'PAGAMENTO';
} else if (['sim','confirmo'].includes(normalized)) {
  responseType = 'PEDIDO';
  nextStage = 'PEDIDO';
} else if (/^\d+$/i.test(text) && Number(text) > 0 && Number(text) <= 999) {
  responseType = 'SELECIONAR_PRODUTO';
  nextStage = 'CARRINHO';
} else {
  responseType = 'MENU';
  nextStage = 'INICIO';
}

return {
  ...payload,
  responseType,
  nextStage,
  cart: dados.carrinho || [],
  total: dados.valor_total || 0
};

const rows = $json.rows || [];

if (!rows.length) {
  return {
    message: 'No momento não há produtos disponíveis. Tente novamente em breve.',
    instance: $json.instance || 'default',
    phone: $json.phone || ''
  };
}

const catalog = rows.map((p, idx) => `${idx + 1}. ${p.nome} - R$ ${Number(p.preco).toFixed(2)}
${p.descricao || ''}`).join('

');

return {
  message: '🛍️ Catálogo da loja

' + catalog + '

Digite o número do produto para adicionar ao carrinho ou envie 0 para voltar ao menu.',
  instance: $json.instance || 'default',
  phone: $json.phone || ''
};

const selected = Number(($json.text || '').trim());
const products = $json.rows || [];
const product = products[selected - 1];

if (!product) {
  return {
    message: 'Produto inválido. Digite o número do item do catálogo.',
    phone: $json.phone,
    instance: $json.instance,
    retry: true
  };
}

const cart = $json.cart || [];
const existing = cart.find(item => item.produto_id === product.id);

if (existing) {
  existing.quantidade += 1;
} else {
  cart.push({
    produto_id: product.id,
    nome: product.nome,
    quantidade: 1,
    preco_unitario: Number(product.preco)
  });
}

const total = cart.reduce((sum, item) => sum + (Number(item.preco_unitario) * item.quantidade), 0);

return {
  phone: $json.phone,
  instance: $json.instance,
  cart,
  valor_total: Number(total.toFixed(2)),
  message: `✅ Produto adicionado ao carrinho:
${product.nome}

Carrinho atual:
${cart.map(item => `- ${item.nome} x${item.quantidade} = R$ ${(Number(item.preco_unitario) * item.quantidade).toFixed(2)}`).join('
')}

Total: R$ ${Number(total.toFixed(2))}

Digite 3 para fechar o pedido ou 1 para continuar comprando.`,
  nextStep: 'CONFIRMAR'
};

const cart = $json.cart || [];
const total = Number($json.valor_total || 0);

const orderResume = cart.map(item => `${item.nome} x${item.quantidade} - R$ ${(Number(item.preco_unitario) * item.quantidade).toFixed(2)}`).join('
');

return {
  phone: $json.phone,
  instance: $json.instance,
  message: `✅ Pedido confirmado!

${orderResume}

Total: R$ ${total.toFixed(2)}

Vou gerar o Pix para você.`,
  cart,
  total
};

const pedidoId = ($json.rows && $json.rows[0] && $json.rows[0].id) || null;
const cart = $json.cart || [];
const total = Number($json.total || 0);

const pix = '00020126' + '...' + '52040000';

return {
  phone: $json.phone,
  instance: $json.instance,
  pedidoId,
  cart,
  total,
  pixCopiaCola: pix,
  message: `💳 Pagamento via Pix

Pedido #${pedidoId || 'novo'}
Total: R$ ${total.toFixed(2)}

Código Pix:
${pix}

Após pagar, me avise 'PAGO' para confirmar.`,
  nextStep: 'PAGAMENTO'
};
